CookingScene::CookingScene(SceneTransitionOwner next, GameStateSaveImage * image, u8 show_recipes)
    : core(new CookingSceneCore(image, show_recipes)), continuation(next)
{
}

inline CookingSceneCoreOwner::~CookingSceneCoreOwner() { delete value; }

CookingScene::~CookingScene()
{
}

SceneTransitionOwner CookingScene::Run()
{
    core.value->Run();
    return continuation;
}

